// Sport definitions (ARCHITECTURE.md §5). Clients render scoreboards and
// scoring pads purely from these entries, so adding a sport here needs no
// client change. Period naming beyond the regulation list (overtime, extra
// innings, volleyball sets) is generated by the helpers below.
//
// `overtime.naming` says how overtime periods are numbered, for clients too:
// 'prefix' = OT, 2OT, 3OT (Overtime, 2nd Overtime …); 'suffix' = OT1, OT2
// (Overtime 1, Overtime 2); 'innings' = the regulation pattern continues
// (baseball half-innings: Top 8th ▲8 …).

const QUARTERS = [
  { label: '1st Quarter', short: 'Q1' },
  { label: '2nd Quarter', short: 'Q2' },
  { label: '3rd Quarter', short: 'Q3' },
  { label: '4th Quarter', short: 'Q4' },
];

const BASEBALL_INNINGS = 7;
const VOLLEYBALL_BEST_OF = [3, 5];

export function ordinal(n) {
  const mod100 = n % 100;
  if (mod100 >= 11 && mod100 <= 13) return `${n}th`;
  switch (n % 10) {
    case 1: return `${n}st`;
    case 2: return `${n}nd`;
    case 3: return `${n}rd`;
    default: return `${n}th`;
  }
}

function halfInning(index) {
  const inning = Math.floor(index / 2) + 1;
  const top = index % 2 === 0;
  return { label: `${top ? 'Top' : 'Bottom'} ${ordinal(inning)}`, short: `${top ? '▲' : '▼'}${inning}` };
}

function volleyballSets(bestOf) {
  return Array.from({ length: bestOf }, (_, i) => ({ label: `Set ${i + 1}`, short: `S${i + 1}` }));
}

function deepFreeze(value) {
  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const child of Object.values(value)) deepFreeze(child);
  }
  return value;
}

export const SPORTS = deepFreeze({
  basketball: {
    name: 'Basketball',
    symbol: 'basketball.fill',
    scoreMode: 'points',
    periods: QUARTERS,
    overtime: { label: 'Overtime', short: 'OT', max: null, naming: 'prefix' },
    scoring: [
      { points: 1, label: '+1' },
      { points: 2, label: '+2' },
      { points: 3, label: '+3' },
    ],
    clock: { available: true, defaultEnabled: true, periodMinutes: 8, overtimeMinutes: 4 },
    notes: ['Timeout', 'Halftime', 'End of Quarter'],
  },
  football: {
    name: 'Football',
    symbol: 'football.fill',
    scoreMode: 'points',
    periods: QUARTERS,
    overtime: { label: 'Overtime', short: 'OT', max: null, naming: 'prefix' },
    scoring: [
      { points: 6, label: 'TD' },
      { points: 3, label: 'FG' },
      { points: 1, label: 'PAT' },
      { points: 2, label: '2-PT' },
      { points: 2, label: 'Safety' },
    ],
    clock: { available: true, defaultEnabled: true, periodMinutes: 12, overtimeMinutes: 0 },
    notes: ['Timeout', 'Halftime', 'End of Quarter', 'Injury'],
  },
  soccer: {
    name: 'Soccer',
    symbol: 'soccerball',
    scoreMode: 'points',
    periods: [
      { label: '1st Half', short: '1H' },
      { label: '2nd Half', short: '2H' },
    ],
    overtime: { label: 'Overtime', short: 'OT', max: 2, naming: 'suffix' },
    scoring: [{ points: 1, label: 'Goal' }],
    clock: { available: true, defaultEnabled: true, periodMinutes: 40, overtimeMinutes: 10 },
    notes: ['Halftime', 'Injury', 'Weather Delay', 'Penalty Kicks'],
  },
  volleyball: {
    name: 'Volleyball',
    symbol: 'volleyball.fill',
    scoreMode: 'sets',
    periods: volleyballSets(3),
    overtime: null,
    scoring: [{ points: 1, label: 'Point' }],
    clock: { available: false },
    notes: ['Timeout', 'Between Sets'],
    defaults: { bestOf: 3 },
  },
  baseball: {
    name: 'Baseball',
    symbol: 'baseball.fill',
    scoreMode: 'points',
    tracksOuts: true,
    periods: Array.from({ length: BASEBALL_INNINGS * 2 }, (_, i) => halfInning(i)),
    overtime: { label: 'Extra Innings', short: 'XI', max: null, naming: 'innings' },
    scoring: [{ points: 1, label: 'Run' }],
    clock: { available: false },
    notes: ['Pitching Change', 'Rain Delay', 'Mid-Inning'],
  },
});

export function getSport(sportId) {
  return Object.hasOwn(SPORTS, sportId) ? SPORTS[sportId] : null;
}

export function sportIds() {
  return Object.keys(SPORTS);
}

export function volleyballBestOfValues() {
  return VOLLEYBALL_BEST_OF;
}

// Options a new game gets when the admin does not specify them.
export function defaultOptions(sportId) {
  const sport = getSport(sportId);
  if (!sport) throw new Error(`Unknown sport ${sportId}`);
  const clock = sport.clock.available;
  return {
    clockEnabled: clock ? Boolean(sport.clock.defaultEnabled) : false,
    periodMinutes: clock ? sport.clock.periodMinutes : null,
    overtimeMinutes: clock && sport.overtime ? sport.clock.overtimeMinutes : null,
    bestOf: sport.scoreMode === 'sets' ? (sport.defaults?.bestOf ?? 3) : null,
  };
}

export function periodCount(sportId, options = {}) {
  const sport = getSport(sportId);
  if (sport.scoreMode === 'sets') return options.bestOf ?? sport.defaults?.bestOf ?? sport.periods.length;
  return sport.periods.length;
}

// Highest valid 0-based period index, or null when overtime is unlimited.
export function maxPeriodIndex(sportId, options = {}) {
  const sport = getSport(sportId);
  const count = periodCount(sportId, options);
  if (!sport.overtime) return count - 1;
  if (sport.overtime.max === null || sport.overtime.max === undefined) return null;
  return count - 1 + sport.overtime.max;
}

export function periodInfo(sportId, options, index) {
  const sport = getSport(sportId);
  const count = periodCount(sportId, options);
  if (sport.scoreMode === 'sets') {
    return { label: `Set ${index + 1}`, short: `S${index + 1}`, isOvertime: index >= count };
  }
  if (index < count) return { ...sport.periods[index], isOvertime: false };

  const naming = sport.overtime.naming ?? 'prefix';
  if (naming === 'innings') return { ...halfInning(index), isOvertime: true };

  const n = index - count + 1;
  const { label, short } = sport.overtime;
  if (naming === 'suffix') return { label: `${label} ${n}`, short: `${short}${n}`, isOvertime: true };
  return {
    label: n === 1 ? label : `${ordinal(n)} ${label}`,
    short: n === 1 ? short : `${n}${short}`,
    isOvertime: true,
  };
}

// Minutes on the clock for a period; 0 means the period has no clock.
export function periodClockMinutes(sportId, options, index) {
  const sport = getSport(sportId);
  if (!sport.clock.available || !options.clockEnabled) return 0;
  const minutes = index < periodCount(sportId, options) ? options.periodMinutes : options.overtimeMinutes;
  return Number.isFinite(minutes) && minutes > 0 ? minutes : 0;
}

const rulesCache = new Map();

// The SPORTS entry (plus its id) as clients see it; volleyball's set list is
// expanded for the game's bestOf.
export function rulesFor(sportId, options = {}) {
  const sport = getSport(sportId);
  const bestOf = sport.scoreMode === 'sets' ? periodCount(sportId, options) : null;
  const key = `${sportId}:${bestOf ?? ''}`;
  let rules = rulesCache.get(key);
  if (!rules) {
    rules = deepFreeze({
      id: sportId,
      ...structuredClone(sport),
      ...(bestOf ? { periods: volleyballSets(bestOf) } : {}),
    });
    rulesCache.set(key, rules);
  }
  return rules;
}

export function allRules() {
  return Object.fromEntries(sportIds().map((id) => [id, rulesFor(id, defaultOptions(id))]));
}
